    function run(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public payable {
        require(address(this) != c.DEPOSITOR_ACCOUNT(), "test contract must not be depositor");

        uint256 overheadBefore = c.l1FeeOverhead(); if (__ESBMC_reverted()) return;
        uint256 scalarBefore = c.l1FeeScalar(); if (__ESBMC_reverted()) return;
        uint256 balanceBefore = address(c).balance;

        bool reverted;
        c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
