        vm.assume(address(this) != c.DEPOSITOR_ACCOUNT());
        uint256 overheadBefore;
        try c.l1FeeOverhead() returns (uint256 __r) { overheadBefore = __r; } catch { return; }
        uint256 scalarBefore;
        try c.l1FeeScalar() returns (uint256 __r) { scalarBefore = __r; } catch { return; }
        uint256 balanceBefore = address(c).balance;
        bool reverted;
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
